/**
 * Jinx Pit-Hag + Village Idiot: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Pit-Hag
 * Wiki: https://wiki.bloodontheclocktower.com/Village_Idiot
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { jinxedPartners, jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';

describe('Pit-Hag + Village Idiot jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'pithag', 'villageidiot');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('pithag')?.name).toBe('Pit-Hag');
		expect(data.byId.get('villageidiot')?.name).toBe('Village Idiot');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['pithag', 'villageidiot'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['pithag'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['villageidiot'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: given a spare token, the Pit-Hag may make another Village Idiot, though one
	// is in play. Its picker keeps the in-play Village Idiot.
	it("lets the Pit-Hag's picker offer the Village Idiot while one is in play", () => {
		expect(jinxRulesBetween('pithag', 'villageidiot')).toEqual({ spareToken: true });
		expect(jinxedPartners('pithag', 'spareToken', ['pithag', 'villageidiot', 'chef'])).toEqual([
			'villageidiot'
		]);
		expect(jinxedPartners('pithag', 'spareToken', ['pithag', 'chef'])).toEqual([]);
	});
});
